using AcademyDesk.Api.Data;using AcademyDesk.Api.Domain.Entities;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;namespace AcademyDesk.Api.Controllers;
[ApiController][Route("api/academies/{academyId:guid}/course-modules")]public sealed class CourseModulesController(AcademyDeskDbContext db):ControllerBase{[HttpGet]public async Task<ActionResult> List(Guid academyId,Guid? courseId,CancellationToken t){var q=db.CourseModules.AsNoTracking().Where(x=>x.AcademyId==academyId);if(courseId.HasValue)q=q.Where(x=>x.CourseId==courseId);return Ok(await q.OrderBy(x=>x.Sequence).Select(x=>new{x.Id,x.CourseId,x.Title,x.Description,x.Sequence,x.IsPublished}).ToListAsync(t));}[HttpPost]public async Task<ActionResult> Create(Guid academyId,CreateModule r,CancellationToken t){if(string.IsNullOrWhiteSpace(r.Title)||!await db.Courses.AnyAsync(x=>x.Id==r.CourseId&&x.AcademyId==academyId,t))return BadRequest(new{message="Valid course and title required."});db.CourseModules.Add(new CourseModule{AcademyId=academyId,CourseId=r.CourseId,Title=r.Title.Trim(),Description=r.Description?.Trim(),Sequence=r.Sequence,IsPublished=false});await db.SaveChangesAsync(t);return Ok();}[HttpPatch("{moduleId:guid}/publication")]public async Task<ActionResult> SetPublication(Guid academyId,Guid moduleId,PublicationRequest r,CancellationToken t){var module=await db.CourseModules.SingleOrDefaultAsync(x=>x.Id==moduleId&&x.AcademyId==academyId,t);if(module is null)return NotFound();module.IsPublished=r.IsPublished;await db.SaveChangesAsync(t);return Ok(new{module.Id,module.IsPublished});}}
public sealed record CreateModule(Guid CourseId,string Title,string? Description,int Sequence);
public sealed record PublicationRequest(bool IsPublished);
